	for _, other := range []string{
		OperationID("0000000000VDVZT0DFJNS2394R", "ctrl-b", PhaseCanary, 0), OperationID("0000000000GBSYKHMNVHNRT6RH", "ctrl-c", PhaseCanary, 0),
