func controllers() []Unit {
	return []Unit{{ID: "ctrl-a", Group: "controllers", Seed: true}, {ID: "ctrl-b", Group: "controllers"}, {ID: "ctrl-c", Group: "controllers"}}
}

func seats() []Unit {
	return []Unit{
		{ID: "p1-a", Group: "p1"}, {ID: "p1-b", Group: "p1"},
		{ID: "p2-a", Group: "p2"}, {ID: "p2-b", Group: "p2"},
	}
}

func testPolicy() Policy {
	policy := DefaultPolicy()
	policy.MinHealthyReports = 2
	return policy
}

func newRecord(t *testing.T, units []Unit, policy Policy) Record {
	t.Helper()
	record, err := New(Spec{
		RolloutID: "0000000000039PRXZD4Z9STA2E", Kind: KindController, Cell: "gru", FromDigest: fromDigest, ToDigest: toDigest,
		Units: units, Policy: policy, AuthorityEpoch: 7,
	}, testStart)
	if err != nil {
		t.Fatal(err)
	}
	return record
}

func apply(t *testing.T, record Record, event Event) Record {
	t.Helper()
	next, err := Apply(record, event)
	if err != nil {
		t.Fatalf("%s at %s: %v", event.Kind, record.Phase, err)
	}
	return next
}

func health(at time.Time, pid int64) Health {
	return Health{Digest: toDigest, ProcessID: pid, StartNonce: fmt.Sprintf("%032x", pid), ObservedAt: at}
}

func soakWave(t *testing.T, record Record, at time.Time) (Record, time.Time) {
	t.Helper()
	wave := record.WaveIndex
	for _, id := range record.Waves[wave] {
		record = apply(t, record, Event{Kind: EventPrepared, Unit: id, At: at})
	}
	soak := record.soakDuration()
	for report := range record.Policy.MinHealthyReports {
		at = at.Add(time.Second)
		for _, id := range record.Waves[wave] {
			if record.Phase.Terminal() || record.WaveIndex != wave {
				break
			}
			record = apply(t, record, Event{Kind: EventHealthy, Unit: id, Health: health(at, 100), At: at})
		}
		_ = report
	}
	// The observations themselves must span the soak window: every unit
	// reports again once the window has passed.
	at = at.Add(soak)
	for _, id := range record.Waves[wave] {
		if record.Phase.Terminal() || record.WaveIndex != wave {
			break
		}
		record = apply(t, record, Event{Kind: EventHealthy, Unit: id, Health: health(at, 100), At: at})
	}
	if record.Phase.Terminal() {
		return record, at
	}
	return apply(t, record, Event{Kind: EventTick, At: at}), at
}

func requireRollingBack(t *testing.T, record Record, reason string) {
	t.Helper()
	if record.Phase != PhaseRollingBack || !slices.Contains(record.KnownBad, toDigest) || !strings.Contains(record.Reason, reason) {
		t.Fatalf("phase=%s known_bad=%v reason=%q; want rolling-back with %q", record.Phase, record.KnownBad, record.Reason, reason)
	}
	for _, action := range NextActions(record) {
		if action.Kind != ActionRollback || action.Digest != fromDigest {
			t.Fatalf("rollback emitted %+v", action)
		}
	}
}

func checkInvariants(t *testing.T, seed uint64, before, after Record) {
	t.Helper()
	if err := after.Validate(); err != nil {
		t.Fatalf("seed %d: invalid record: %v", seed, err)
	}
	limit := max(after.Policy.BatchSize, after.Policy.CanaryUnits)
	inFlight := after.InFlight()
	if len(inFlight) > limit {
		t.Fatalf("seed %d: %d units in flight exceeds %d", seed, len(inFlight), limit)
	}
	groups := map[string]bool{}
	for _, id := range inFlight {
		group := after.Units[id].Group
		if groups[group] {
			t.Fatalf("seed %d: two units of %s in flight", seed, group)
		}
		groups[group] = true
	}
	knownBad := slices.Contains(after.KnownBad, after.ToDigest)
	if slices.Contains(before.KnownBad, before.ToDigest) && !knownBad {
		t.Fatalf("seed %d: known-bad target was forgotten", seed)
	}
	for _, action := range NextActions(after) {
		if knownBad && action.Kind == ActionPrepare {
			t.Fatalf("seed %d: prepare of a known-bad target", seed)
		}
		if action.Kind == ActionRollback && action.Digest != after.FromDigest {
			t.Fatalf("seed %d: rollback towards %s", seed, action.Digest)
		}
	}
	if after.Phase == PhaseRollingBack && !knownBad {
		t.Fatalf("seed %d: rollback started before the target was known bad", seed)
	}
	if after.AuthorityEpoch != before.AuthorityEpoch {
		t.Fatalf("seed %d: a transition changed the authority epoch", seed)
	}
	if after.Phase.preparing() || after.Phase.soaking() {
		for id, progress := range after.Units {
			if progress.Seed && progress.State != UnitPending && after.WaveIndex != len(after.Waves)-1 {
				t.Fatalf("seed %d: seed %s moved before the last wave", seed, id)
			}
		}
	}
}

func New(spec Spec, now time.Time) (Record, error) {
	if now.IsZero() || spec.StartedAt.After(now) {
		return Record{}, fmt.Errorf("%w: start time", ErrInvalid)
	}
	if slices.Contains(spec.KnownBad, spec.ToDigest) {
		return Record{}, ErrKnownBad
	}
	waves, err := PlanWaves(spec.Units, spec.Policy)
	if err != nil {
		return Record{}, err
	}
	policyDigest, err := spec.Policy.Digest()
	if err != nil {
		return Record{}, err
	}
	units := make(map[string]UnitProgress, len(spec.Units))
	for _, unit := range spec.Units {
		units[unit.ID] = UnitProgress{State: UnitPending, Group: unit.Group, Seed: unit.Seed}
	}
	for wave, ids := range waves {
		for _, id := range ids {
			progress := units[id]
			progress.Wave = wave
			units[id] = progress
		}
	}
	knownBad := slices.Clone(spec.KnownBad)
	slices.Sort(knownBad)
	started := spec.StartedAt
	if started.IsZero() {
		started = now
	}
	record := Record{
		SchemaVersion: SchemaVersion, RolloutID: spec.RolloutID, Kind: spec.Kind, Cell: spec.Cell,
		FromDigest: spec.FromDigest, ToDigest: spec.ToDigest, Policy: spec.Policy, PolicyDigest: policyDigest,
		Phase: PhasePending, Waves: waves, Units: units, KnownBad: slices.Compact(knownBad),
		StartedAt: started.UTC(), PhaseStartedAt: now.UTC(), AuthorityEpoch: spec.AuthorityEpoch,
	}
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	return record, nil
}

func Apply(record Record, event Event) (Record, error) {
	if err := record.Validate(); err != nil {
		return Record{}, err
	}
	if event.At.IsZero() || len(event.Reason) > maxReason {
		return Record{}, fmt.Errorf("%w: event time or reason", ErrInvalid)
	}
	if record.Phase.Terminal() {
		return Record{}, ErrTerminal
	}
	next := record.Clone()
	at := event.At.UTC()
	if completionEvent(event.Kind) || event.Kind == EventStart {
		// A completion that arrives after its phase deadline must not erase
		// that deadline: enforce it first, exactly as a tick at the same
		// instant would, and drop the late completion if it fired.
		phase, wave := next.Phase, next.WaveIndex
		next.tick(at)
		if next.Phase != phase || next.WaveIndex != wave {
			if err := next.Validate(); err != nil {
				return Record{}, err
			}
			return next, nil
		}
	}
	var err error
	switch event.Kind {
	case EventStart:
		err = next.start(at)
	case EventPreflightPassed:
		err = next.preflightPassed(at)
	case EventPreflightFailed:
		err = next.requirePhase(PhasePreflight)
		if err == nil {
			next.finish(PhaseAborted, at, reasonOr(event.Reason, "preflight failed"))
		}
	case EventPrepared:
		err = next.prepared(event.Unit, at)
	case EventHealthy:
		err = next.healthy(event.Unit, event.Health, at)
	case EventUnhealthy, EventHeld:
		// A held forward step rolls back like an unhealthy one; rollback
		// itself, not the forward unit, is what freezes for a human.
		err = next.failed(event.Unit, at, reasonOr(event.Reason, string(event.Kind)))
	case EventRollbackServing:
		err = next.rollbackServing(event.Unit, at)
	case EventRollbackHeld:
		err = next.rollbackHeld(event.Unit, at, reasonOr(event.Reason, "rollback held"))
	case EventTick:
		next.tick(at)
	case EventAbort:
		err = next.abort(at, reasonOr(event.Reason, "operator abort"))
	case EventFreeze:
		if next.Phase == PhaseFrozen {
			return Record{}, ErrInvalidTransition
		}
		next.enter(PhaseFrozen, at, time.Time{}, reasonOr(event.Reason, "frozen"))
	case EventResume:
		err = next.resume(at, event.Left)
	default:
		err = fmt.Errorf("%w: event kind", ErrInvalid)
	}
	if err != nil {
		return Record{}, err
	}
	if err := next.Validate(); err != nil {
		return Record{}, err
	}
	return next, nil
}

func completionEvent(kind EventKind) bool {
	return kind == EventPreflightPassed || kind == EventPrepared || kind == EventHealthy
}

func boundReason(reason string) string {
	if len(reason) <= maxReason {
		return reason
	}
	const ellipsis = "..."
	cut := maxReason - len(ellipsis)
	for cut > 0 && !utf8.RuneStart(reason[cut]) {
		cut--
	}
	return reason[:cut] + ellipsis
}

func reasonOr(reason, fallback string) string {
	if reason == "" {
		return fallback
	}
	return reason
}

func (record *Record) requirePhase(phases ...Phase) error {
	if !slices.Contains(phases, record.Phase) {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

func (record *Record) enter(phase Phase, at, deadline time.Time, reason string) {
	if (phase == PhasePreflight || phase.preparing() || phase.soaking()) && deadline.After(record.StartedAt.Add(ObservationBudget)) {
		deadline = record.StartedAt.Add(ObservationBudget)
	}
	record.Phase = phase
	record.PhaseStartedAt = at
	record.PhaseDeadline = deadline
	record.Reason = boundReason(reason)
}

func (record *Record) finish(phase Phase, at time.Time, reason string) {
	record.enter(phase, at, time.Time{}, reason)
}

func (record *Record) start(at time.Time) error {
	if err := record.requirePhase(PhasePending); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.enter(PhasePreflight, at, at.Add(seconds(record.Policy.PreflightSeconds)), "")
	return nil
}

func (record *Record) preflightPassed(at time.Time) error {
	if err := record.requirePhase(PhasePreflight); err != nil {
		return err
	}
	if slices.Contains(record.KnownBad, record.ToDigest) {
		record.finish(PhaseAborted, at, "target digest is known bad")
		return nil
	}
	record.beginWave(0, at)
	return nil
}

func (record *Record) beginWave(wave int, at time.Time) {
	record.WaveIndex = wave
	phase := PhaseBatch
	if wave == 0 {
		phase = PhaseCanary
	}
	for _, id := range record.Waves[wave] {
		progress := record.Units[id]
		progress.State = UnitPreparing
		progress.HealthyReports, progress.FirstHealthyAt, progress.ProcessID, progress.StartNonce = 0, time.Time{}, 0, ""
		progress.LastHealthyAt = time.Time{}
		record.Units[id] = progress
	}
	record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
}

func (record *Record) currentWaveUnit(unit string) (UnitProgress, error) {
	progress, exists := record.Units[unit]
	if !exists || progress.Wave != record.WaveIndex {
		return UnitProgress{}, fmt.Errorf("%w: unit %q is not in the current wave", ErrInvalidTransition, unit)
	}
	return progress, nil
}

func (record *Record) prepared(unit string, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	switch progress.State {
	case UnitSoaking:
		return nil
	case UnitPreparing:
	default:
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	progress.State = UnitSoaking
	record.Units[unit] = progress
	if record.Phase.preparing() && record.waveState(UnitSoaking) {
		phase := PhaseBatchSoak
		if record.Phase == PhaseCanary {
			phase = PhaseCanarySoak
		}
		record.enter(phase, at, at.Add(seconds(record.Policy.ProofDeadlineSeconds)), "")
	}
	return nil
}

func (record *Record) waveState(state UnitState) bool {
	for _, id := range record.Waves[record.WaveIndex] {
		if record.Units[id].State != state {
			return false
		}
	}
	return true
}

func (record *Record) healthy(unit string, health Health, at time.Time) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, err := record.currentWaveUnit(unit)
	if err != nil {
		return err
	}
	if progress.State != UnitSoaking {
		return fmt.Errorf("%w: unit %q is %s", ErrInvalidTransition, unit, progress.State)
	}
	if health.ProcessID <= 0 || !nonceRE.MatchString(health.StartNonce) || health.ObservedAt.IsZero() {
		return fmt.Errorf("%w: health report identity", ErrInvalid)
	}
	if health.ObservedAt.Before(record.PhaseStartedAt) || health.ObservedAt.After(at.Add(time.Minute)) {
		// A report older than the current phase cannot prove the new
		// process, in the preparing phase as little as in the soak: a
		// replayed report would start the soak clock in the past.
		return fmt.Errorf("%w: stale or future health report", ErrInvalid)
	}
	if health.Digest != record.ToDigest {
		record.startRollback(at, fmt.Sprintf("unit %s serves an unexpected digest", unit))
		return nil
	}
	if progress.HealthyReports > 0 && (progress.ProcessID != health.ProcessID || progress.StartNonce != health.StartNonce) {
		record.startRollback(at, fmt.Sprintf("unit %s restarted during soak", unit))
		return nil
	}
	observed := health.ObservedAt.UTC()
	if progress.HealthyReports > 0 && !observed.After(progress.LastHealthyAt) {
		// A replayed or reordered report proves nothing new.
		return nil
	}
	if progress.HealthyReports == 0 {
		progress.FirstHealthyAt = observed
		progress.ProcessID, progress.StartNonce = health.ProcessID, health.StartNonce
	}
	progress.LastHealthyAt = observed
	progress.HealthyReports++
	record.Units[unit] = progress
	record.advanceIfSoaked(at)
	return nil
}

func (record *Record) failed(unit string, at time.Time, reason string) error {
	if !record.Phase.preparing() && !record.Phase.soaking() {
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	progress, exists := record.Units[unit]
	if !exists || !progress.State.touched() {
		return fmt.Errorf("%w: unit %q has not moved", ErrInvalidTransition, unit)
	}
	record.startRollback(at, fmt.Sprintf("unit %s: %s", unit, reason))
	return nil
}

func (record *Record) soakDuration() time.Duration {
	if record.Phase == PhaseCanarySoak {
		return seconds(record.Policy.CanarySoakSeconds)
	}
	return seconds(record.Policy.BatchSoakSeconds)
}

func (record *Record) advanceIfSoaked(at time.Time) {
	if !record.Phase.soaking() {
		return
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		// The observations, not elapsed tick time, must span the window: a
		// unit that stopped reporting early never completes its soak.
		if progress.State != UnitSoaking || progress.HealthyReports < record.Policy.MinHealthyReports ||
			progress.LastHealthyAt.Before(progress.FirstHealthyAt.Add(record.soakDuration())) {
			return
		}
	}
	for _, id := range record.Waves[record.WaveIndex] {
		progress := record.Units[id]
		progress.State = UnitPromoted
		record.Units[id] = progress
	}
	if record.WaveIndex+1 < len(record.Waves) {
		record.beginWave(record.WaveIndex+1, at)
		return
	}
	record.finish(PhaseComplete, at, "")
}

func (record *Record) tick(at time.Time) {
	if (record.Phase == PhasePending || record.Phase == PhasePreflight || record.Phase.preparing() || record.Phase.soaking()) &&
		!at.Before(record.StartedAt.Add(ObservationBudget)) {
		reason := "release exceeded its fixed 20-minute observation budget"
		if record.Phase == PhasePending || record.Phase == PhasePreflight {
			record.finish(PhaseAborted, at, reason)
		} else {
			record.startRollback(at, reason)
		}
		return
	}
	switch {
	case record.Phase == PhasePreflight && !at.Before(record.PhaseDeadline):
		record.finish(PhaseAborted, at, "preflight deadline exceeded")
	case record.Phase.preparing() && !at.Before(record.PhaseDeadline):
		record.startRollback(at, "prepare deadline exceeded")
	case record.Phase.soaking():
		if !at.Before(record.PhaseDeadline) {
			for _, id := range record.Waves[record.WaveIndex] {
				if record.Units[id].HealthyReports == 0 {
					record.startRollback(at, fmt.Sprintf("unit %s missed its serving-proof deadline", id))
					return
				}
			}
		}
		wave := record.WaveIndex
		record.advanceIfSoaked(at)
		// Every unit that proved itself before the serving-proof deadline
		// has finished its soak window by deadline+soak, and has reported
		// again within minSoakGap after it. A wave still soaking then has a
		// unit that stopped reporting (for example a hung process after one
		// healthy report); it must not hold the cell's rollout slot forever.
		if record.Phase.soaking() && record.WaveIndex == wave &&
			!at.Before(record.PhaseDeadline.Add(record.soakDuration()).Add(minSoakGap)) {
			record.startRollback(at, "soak did not complete before its deadline")
		}
	case record.Phase == PhaseRollingBack && !at.Before(record.PhaseDeadline):
		head := record.rollbackHead()
		if head != "" {
			progress := record.Units[head]
			progress.State = UnitHeld
			record.Units[head] = progress
		}
		record.enter(PhaseFrozen, at, time.Time{}, "rollback deadline exceeded")
	}
}

func (record *Record) startRollback(at time.Time, reason string) {
	if !slices.Contains(record.KnownBad, record.ToDigest) {
		record.KnownBad = append(record.KnownBad, record.ToDigest)
		slices.Sort(record.KnownBad)
		if len(record.KnownBad) > MaxKnownBad {
			// Keep the current target; the cell list retains the dropped entry.
			drop := 0
			if record.KnownBad[0] == record.ToDigest {
				drop = 1
			}
			record.KnownBad = slices.Delete(record.KnownBad, drop, drop+1)
		}
	}
	var touched []string
	for id, progress := range record.Units {
		if progress.State.touched() {
			touched = append(touched, id)
		}
	}
	slices.SortFunc(touched, func(a, b string) int {
		if order := cmp.Compare(record.Units[b].Wave, record.Units[a].Wave); order != 0 {
			return order
		}
		return cmp.Compare(b, a)
	})
	for _, id := range touched {
		progress := record.Units[id]
		progress.State = UnitRollingBack
		record.Units[id] = progress
	}
	record.RollbackOrder = touched
	if len(touched) == 0 {
		record.finish(PhaseRolledBack, at, reason)
		return
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), reason)
}

func (record *Record) rollbackHead() string {
	for _, id := range record.RollbackOrder {
		if record.Units[id].State == UnitRollingBack {
			return id
		}
	}
	return ""
}

func (record *Record) rollbackServing(unit string, at time.Time) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		if progress, exists := record.Units[unit]; exists && progress.State == UnitRolledBack {
			return nil
		}
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitRolledBack
	record.Units[unit] = progress
	if record.rollbackHead() == "" {
		record.finish(PhaseRolledBack, at, record.Reason)
		return nil
	}
	record.enter(PhaseRollingBack, at, at.Add(seconds(record.Policy.RollbackDeadlineSeconds)), record.Reason)
	return nil
}

func (record *Record) rollbackHeld(unit string, at time.Time, reason string) error {
	if err := record.requirePhase(PhaseRollingBack); err != nil {
		return err
	}
	if head := record.rollbackHead(); head != unit {
		return fmt.Errorf("%w: unit %q is not the rollback head", ErrInvalidTransition, unit)
	}
	progress := record.Units[unit]
	progress.State = UnitHeld
	record.Units[unit] = progress
	// Never retarget ToDigest: a held rollback stops for a human.
	record.enter(PhaseFrozen, at, time.Time{}, reason)
	return nil
}

func (record *Record) abort(at time.Time, reason string) error {
	switch {
	case record.Phase == PhasePending || record.Phase == PhasePreflight:
		record.finish(PhaseAborted, at, reason)
	case record.Phase.preparing() || record.Phase.soaking():
		record.startRollback(at, reason)
	default:
		return fmt.Errorf("%w: %s", ErrInvalidTransition, record.Phase)
	}
	return nil
}

func (record *Record) resume(at time.Time, left []string) error {
	if err := record.requirePhase(PhaseFrozen); err != nil {
		return err
	}
	for _, id := range left {
		if progress, in := record.Units[id]; in && progress.State.touched() {
			progress.State = UnitRolledBack
			record.Units[id] = progress
		}
	}
	for id, progress := range record.Units {
		if progress.State == UnitHeld {
			if progress.Attempts >= record.Policy.MaxRollbackRetries {
				return fmt.Errorf("%w: unit %q exhausted its rollback retries", ErrAttemptsExhausted, id)
			}
			progress.Attempts++
			progress.State = UnitRollingBack
			record.Units[id] = progress
		}
	}
	reason := record.Reason
	pending := record.rollbackHead() != ""
	for _, progress := range record.Units {
		if progress.State == UnitPreparing || progress.State == UnitSoaking || progress.State == UnitPromoted {
			pending = true
		}
	}
	if !pending {
		record.finish(PhaseAborted, at, reason)
		return nil
	}
	// Re-derive the order so units that were frozen mid-forward join it.
	record.startRollback(at, reason)
	return nil
}

func (kind Kind) valid() bool {
	return kind == KindTerraBase || kind == KindWorkload || kind == KindController || kind == KindHost
}

func (phase Phase) Terminal() bool {
	return phase == PhaseComplete || phase == PhaseAborted || phase == PhaseRolledBack
}

func (state UnitState) touched() bool {
	return state == UnitPreparing || state == UnitSoaking || state == UnitPromoted ||
		state == UnitRollingBack || state == UnitHeld
}

func DefaultPolicy() Policy {
	return Policy{
		CanaryUnits: 1, BatchSize: MaxUnits,
		CanarySoakSeconds: int64((5 * time.Minute).Seconds()), BatchSoakSeconds: int64((2 * time.Minute).Seconds()),
		MinHealthyReports: 3, ProofDeadlineSeconds: int64((10 * time.Minute).Seconds()),
		RollbackDeadlineSeconds: int64((10 * time.Minute).Seconds()), PreflightSeconds: int64((10 * time.Minute).Seconds()),
		MaxAttempts: 1, MaxRollbackRetries: 3,
	}
}

func (policy Policy) Validate() error {
	if policy.CanaryUnits < 1 || policy.CanaryUnits > MaxUnits || policy.BatchSize < 1 || policy.BatchSize > MaxUnits ||
		policy.CanarySoakSeconds < 0 || policy.BatchSoakSeconds < 0 || policy.MinHealthyReports < 1 ||
		policy.ProofDeadlineSeconds < 1 || policy.RollbackDeadlineSeconds < 1 || policy.PreflightSeconds < 1 ||
		policy.MaxAttempts < 1 || policy.MaxRollbackRetries < 0 {
		return fmt.Errorf("%w: policy bounds", ErrInvalid)
	}
	return nil
}

func (policy Policy) Digest() (string, error) {
	encoded, err := protocol.EncodeJSON(policy)
	if err != nil {
		return "", err
	}
	sum := sha256.Sum256(encoded)
	return hex.EncodeToString(sum[:]), nil
}

func (record Record) Validate() error {
	if record.SchemaVersion != SchemaVersion || !entityid.Valid(record.RolloutID) || !record.Kind.valid() ||
		!tokenRE.MatchString(record.Cell) || !digestRE.MatchString(record.FromDigest) || !digestRE.MatchString(record.ToDigest) ||
		record.FromDigest == record.ToDigest || record.AuthorityEpoch == 0 || record.StartedAt.IsZero() ||
		record.PhaseStartedAt.IsZero() || len(record.Reason) > maxReason || len(record.KnownBad) > MaxKnownBad {
		return fmt.Errorf("%w: record identity", ErrInvalid)
	}
	if err := record.Policy.Validate(); err != nil {
		return err
	}
	if digest, err := record.Policy.Digest(); err != nil || digest != record.PolicyDigest {
		return fmt.Errorf("%w: policy digest", ErrInvalid)
	}
	switch record.Phase {
	case PhasePending, PhasePreflight, PhaseCanary, PhaseCanarySoak, PhaseBatch, PhaseBatchSoak,
		PhaseComplete, PhaseRollingBack, PhaseFrozen, PhaseAborted, PhaseRolledBack:
	default:
		return fmt.Errorf("%w: phase", ErrInvalid)
	}
	if len(record.Waves) == 0 || len(record.Units) == 0 || len(record.Units) > MaxUnits ||
		record.WaveIndex < 0 || record.WaveIndex >= len(record.Waves) {
		return fmt.Errorf("%w: waves", ErrInvalid)
	}
	seen := make(map[string]struct{}, len(record.Units))
	for wave, ids := range record.Waves {
		if len(ids) == 0 {
			return fmt.Errorf("%w: empty wave", ErrInvalid)
		}
		for _, id := range ids {
			progress, exists := record.Units[id]
			if _, duplicate := seen[id]; duplicate || !exists || progress.Wave != wave || !tokenRE.MatchString(progress.Group) {
				return fmt.Errorf("%w: wave unit %q", ErrInvalid, id)
			}
			seen[id] = struct{}{}
		}
	}
	if len(seen) != len(record.Units) {
		return fmt.Errorf("%w: unit outside every wave", ErrInvalid)
	}
	for _, id := range record.RollbackOrder {
		if _, exists := record.Units[id]; !exists {
			return fmt.Errorf("%w: rollback unit %q", ErrInvalid, id)
		}
	}
	for _, digest := range record.KnownBad {
		if !digestRE.MatchString(digest) {
			return fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
	}
	if slices.Contains(record.KnownBad, record.FromDigest) {
		return fmt.Errorf("%w: rollback target is known bad", ErrInvalid)
	}
	return record.validatePhaseUnits()
}

func (record Record) validatePhaseUnits() error {
	for _, id := range record.Waves[record.WaveIndex] {
		state := record.Units[id].State
		if record.Phase.soaking() && state != UnitSoaking ||
			record.Phase.preparing() && state != UnitPreparing && state != UnitSoaking {
			return fmt.Errorf("%w: phase %s contradicts unit %q in state %s", ErrInvalid, record.Phase, id, state)
		}
	}
	if record.Phase == PhaseRollingBack && record.rollbackHead() == "" {
		return fmt.Errorf("%w: rolling back without a unit to roll back", ErrInvalid)
	}
	return nil
}

func (record Record) abortedBeforeUpdate() bool {
	if record.Phase != PhaseAborted || len(record.RollbackOrder) != 0 {
		return false
	}
	for _, progress := range record.Units {
		if progress.State != UnitPending {
			return false
		}
	}
	return true
}

func (record Record) Clone() Record {
	clone := record
	clone.Waves = make([][]string, len(record.Waves))
	for index, wave := range record.Waves {
		clone.Waves[index] = slices.Clone(wave)
	}
	clone.Units = make(map[string]UnitProgress, len(record.Units))
	for id, progress := range record.Units {
		clone.Units[id] = progress
	}
	clone.RollbackOrder = slices.Clone(record.RollbackOrder)
	clone.KnownBad = slices.Clone(record.KnownBad)
	return clone
}

func (record Record) InFlight() []string {
	var units []string
	for id, progress := range record.Units {
		if progress.State == UnitPreparing || progress.State == UnitSoaking {
			units = append(units, id)
		}
	}
	slices.Sort(units)
	return units
}

func OperationID(rolloutID, unit string, phase Phase, attempt int) string {
	return entityid.Derive("rollout", rolloutID, unit, string(phase), fmt.Sprint(attempt))
}

func PlanWaves(units []Unit, policy Policy) ([][]string, error) {
	if err := policy.Validate(); err != nil {
		return nil, err
	}
	if len(units) == 0 || len(units) > MaxUnits {
		return nil, fmt.Errorf("%w: unit count", ErrInvalid)
	}
	ordered := slices.Clone(units)
	slices.SortFunc(ordered, func(a, b Unit) int { return cmp.Compare(a.ID, b.ID) })
	var seeds, rest []Unit
	seen := make(map[string]struct{}, len(ordered))
	for _, unit := range ordered {
		if !tokenRE.MatchString(unit.ID) || !tokenRE.MatchString(unit.Group) {
			return nil, fmt.Errorf("%w: unit identity %q", ErrInvalid, unit.ID)
		}
		if _, duplicate := seen[unit.ID]; duplicate {
			return nil, fmt.Errorf("%w: duplicate unit %q", ErrInvalid, unit.ID)
		}
		seen[unit.ID] = struct{}{}
		if unit.Seed {
			seeds = append(seeds, unit)
		} else {
			rest = append(rest, unit)
		}
	}
	if len(seeds) > 1 {
		return nil, fmt.Errorf("%w: more than one seed unit", ErrInvalid)
	}
	var waves [][]string
	first := true
	for len(rest) > 0 {
		limit := policy.BatchSize
		if first {
			limit = policy.CanaryUnits
		}
		wave, remaining := takeWave(rest, limit)
		waves = append(waves, wave)
		rest = remaining
		first = false
	}
	for _, seed := range seeds {
		waves = append(waves, []string{seed.ID})
	}
	return waves, nil
}

func takeWave(units []Unit, limit int) ([]string, []Unit) {
	groups := map[string]struct{}{}
	var wave []string
	var remaining []Unit
	for _, unit := range units {
		if _, taken := groups[unit.Group]; len(wave) < limit && !taken {
			groups[unit.Group] = struct{}{}
			wave = append(wave, unit.ID)
			continue
		}
		remaining = append(remaining, unit)
	}
	return wave, remaining
}

func NextActions(record Record) []Action {
	if record.Validate() != nil {
		return nil
	}
	switch {
	case record.Phase == PhasePreflight:
		return []Action{{Kind: ActionPreflight, Deadline: record.PhaseDeadline}}
	case record.Phase.preparing() || record.Phase.soaking():
		var actions []Action
		for _, id := range record.Waves[record.WaveIndex] {
			progress := record.Units[id]
			switch progress.State {
			case UnitPreparing:
				actions = append(actions, Action{
					Kind: ActionPrepare, Unit: id, Digest: record.ToDigest,
					OperationID: OperationID(record.RolloutID, id, record.Phase, progress.Attempts),
					Peers:       record.peers(id), Deadline: record.PhaseDeadline,
				})
			case UnitSoaking:
				actions = append(actions, Action{Kind: ActionAwaitHealth, Unit: id, Digest: record.ToDigest, Deadline: record.PhaseDeadline})
			}
		}
		return actions
	case record.Phase == PhaseRollingBack:
		head := record.rollbackHead()
		if head == "" {
			return nil
		}
		return []Action{{
			Kind: ActionRollback, Unit: head, Digest: record.FromDigest,
			OperationID: OperationID(record.RolloutID, head, PhaseRollingBack, record.Units[head].Attempts),
			Peers:       record.peers(head), Deadline: record.PhaseDeadline,
		}}
	case record.Phase == PhaseFrozen:
		return []Action{{Kind: ActionPage}}
	}
	return nil
}

func (record Record) peers(id string) []string {
	group := record.Units[id].Group
	var peers []string
	for other, progress := range record.Units {
		if other != id && progress.Group == group {
			peers = append(peers, other)
		}
	}
	slices.Sort(peers)
	return peers
}

func (s *Soak) Observe(sample SoakSample) (bool, error) {
	if sample.ArtifactDigest != s.Digest || sample.Phase != s.Promoted || !sample.Serving {
		return false, Terminal(fmt.Errorf("%w: seat left %s serving (artifact %s, phase %s, serving %t)",
			ErrSoakFailed, s.Digest, sample.ArtifactDigest, sample.Phase, sample.Serving))
	}
	if s.first != nil && sample.OperationID != s.first.OperationID {
		return false, Terminal(fmt.Errorf("%w: seat operation changed from %s to %s",
			ErrSoakFailed, s.first.OperationID, sample.OperationID))
	}
	if !s.last.IsZero() && sample.At.Before(s.last) {
		return false, errors.New("soak samples went back in time")
	}
	s.last = sample.At
	// Zero is "no live process reported", not a process: such a sample is
	// unknown like a report gap. It neither sets nor breaks the pinned
	// identity, cannot start the window and cannot complete it, so a soak
	// is only ever passed by the process that started it.
	if sample.Gap || sample.ProcessPID == 0 {
		if s.Window <= 0 {
			// A disabled soak checks only the controller's own fields.
			return true, nil
		}
		if s.reported.IsZero() {
			s.reported = sample.At
		}
		if gap := sample.At.Sub(s.reported); gap > max(s.Window, minSoakGap) {
			return false, Transient(fmt.Errorf("seat has had no current host report for %s during its soak", gap))
		}
		return false, nil
	}
	s.reported = sample.At
	if s.lastPID != 0 && sample.ProcessPID != s.lastPID {
		return false, Terminal(fmt.Errorf("%w: seat process restarted (pid %d -> %d)",
			ErrSoakFailed, s.lastPID, sample.ProcessPID))
	}
	s.lastPID = sample.ProcessPID
	if s.first == nil {
		first := sample
		s.first = &first
		return s.Window <= 0, nil
	}
	return !sample.At.Before(s.first.At.Add(s.Window)), nil
}

func Transient(err error) error {
	if err == nil {
		return nil
	}
	return classified{err: err, class: ClassTransient}
}

func Terminal(err error) error {
	if err == nil {
		return nil
	}
	return classified{err: err, class: ClassTerminal}
}

func Classify(err error) Class {
	var marked classified
	if errors.As(err, &marked) {
		return marked.class
	}
	if errors.Is(err, context.DeadlineExceeded) {
		return ClassTransient
	}
	return ClassTerminal
}

func stageTestRelease(t *testing.T, layout selfupdate.Layout, content, keep string) string {
	t.Helper()
	binary := filepath.Join(t.TempDir(), "binary")
	if err := os.WriteFile(binary, []byte(content), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.Remove(filepath.Join(layout.Root, "current")); err != nil && !errors.Is(err, os.ErrNotExist) {
		t.Fatal(err)
	}
	digest, err := selfupdate.Seed(layout, binary)
	if err != nil {
		t.Fatal(err)
	}
	// Seeded releases carry the baked marker, which pruning keeps; drop it
	// so the release behaves like a staged one.
	if err := os.Remove(filepath.Join(layout.ReleaseDir(digest), "baked")); err != nil {
		t.Fatal(err)
	}
	if keep != "" {
		pointCurrent(t, layout, keep)
	}
	return digest
}

func pointCurrent(t *testing.T, layout selfupdate.Layout, digest string) {
	t.Helper()
	temporary := filepath.Join(layout.Root, ".current-test")
	_ = os.Remove(temporary)
	if err := os.Symlink("releases/"+digest, temporary); err != nil {
		t.Fatal(err)
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, "current")); err != nil {
		t.Fatal(err)
	}
}

func digestOf(content string) string {
	sum := sha256.Sum256([]byte(content))
	return hex.EncodeToString(sum[:])
}

func (r *restarts) restart(_ context.Context, unit string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.fail {
		return errors.New("systemctl failed")
	}
	r.units = append(r.units, unit)
	return nil
}

func (r *restarts) count() int {
	r.mu.Lock()
	defer r.mu.Unlock()
	return len(r.units)
}

func (f *fetchFake) Fetch(_ context.Context, layout selfupdate.Layout, receipt, _ []byte) (string, error) {
	f.calls++
	if f.slow != nil {
		f.slow()
	}
	if string(receipt) != "signed receipt" {
		return "", errors.New("receipt does not verify")
	}
	return stageTestRelease(f.t, layout, f.content, f.keep), nil
}

func newAgentFixture(t *testing.T) *agentFixture {
	t.Helper()
	layout := selfupdate.Layout{Root: filepath.Join(t.TempDir(), "root"), Owner: os.Getuid()}
	from := stageTestRelease(t, layout, "release from", "")
	to := stageTestRelease(t, layout, "release to", from)
	key, keys := testKey(t)
	r := &restarts{}
	now := time.Now().UTC().Truncate(time.Second)
	agent := &Agent{Cell: "gru", Unit: "ctl-b", SystemdUnit: agentUnit, Layout: layout, Leaders: keys,
		Restart: r.restart, Now: func() time.Time { return now }}
	return &agentFixture{agent: agent, key: key, restarts: r, from: from, to: to, now: now}
}

func (f *agentFixture) command(t *testing.T, action StepAction, digest string, epoch uint64) []byte {
	t.Helper()
	command := StepCommand{Schema: StepSchema, Cell: "gru", RolloutID: entityid.Derive("release-controllers", "rel1"), Kind: rollout.KindController,
		Unit: "ctl-b", OperationID: rollout.OperationID(entityid.Derive("release-controllers", "rel1"), "ctl-b", rollout.PhaseCanary, 0),
		Action: action, Digest: digest, Epoch: epoch, ProofWindowSeconds: 600, Receipt: []byte("signed receipt")}
	// A rollback replaces the rejected target; a forward step replaces the
	// predecessor (the other release when it targets the predecessor).
	command.Replaces = f.from
	if action == StepRollback || digest == f.from {
		command.Replaces = f.to
	}
	wire, err := SignStepCommand(command, f.key, f.now, time.Time{})
	if err != nil {
		t.Fatal(err)
	}
	return wire
}

func (f *agentFixture) assertRestored(t *testing.T) {
	t.Helper()
	layout := f.agent.Layout
	if _, pending, err := layout.Pending(); err != nil || pending {
		t.Fatalf("a restore left a pending activation: %v %v", pending, err)
	}
	if current, err := layout.Current(); err != nil || current != f.from {
		t.Fatalf("current = %s %v, want the predecessor", current, err)
	}
	if bad, err := layout.KnownBad(); err != nil || !bad[f.to] {
		t.Fatalf("rejected release is not known bad: %v %v", bad, err)
	}
	if owed, err := layout.RestartPending(agentUnit); err != nil || !owed {
		t.Fatalf("restore left no restart obligation: %v %v", owed, err)
	}
}

func testKey(t *testing.T) (ed25519.PrivateKey, trust.Keyring) {
	t.Helper()
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keys, err := trust.ParseKeyring(public)
	if err != nil {
		t.Fatal(err)
	}
	return private, keys
}

func (a *Agent) now() time.Time {
	if a.Now != nil {
		return a.Now().UTC()
	}
	return time.Now().UTC()
}

func (a *Agent) Handle(ctx context.Context, wire []byte) StepReply {
	command, expires, err := VerifyStepCommand(wire, a.Cell, a.Unit, a.Leaders, a.now())
	if err != nil {
		return StepReply{Unit: a.Unit, Outcome: OutcomeRefused, Reason: "step command did not verify"}
	}
	return a.handle(ctx, command, expires)
}

func (a *Agent) handle(ctx context.Context, command StepCommand, expires time.Time) StepReply {
	reply := StepReply{OperationID: command.OperationID, Unit: a.Unit, Epoch: command.Epoch}
	a.mu.Lock()
	defer a.mu.Unlock()
	window := max(selfupdate.MinProofWindow, min(selfupdate.MaxProofWindow,
		time.Duration(command.ProofWindowSeconds)*time.Second))
	// Nothing, staging included, outlives the signed command.
	stepCtx, cancel := context.WithDeadline(ctx, expires)
	defer cancel()
	reply.Outcome, reply.Reason = a.apply(stepCtx, command, expires, window)
	return reply
}

func (a *Agent) apply(ctx context.Context, command StepCommand, expires time.Time, window time.Duration) (StepOutcome, string) {
	if outcome, reason := a.locked(func() (StepOutcome, string) {
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		return a.admit(command)
	}); outcome != "" {
		return outcome, reason
	}
	if outcome, reason := a.ensureStaged(ctx, command); outcome != "" {
		return outcome, reason
	}
	outcome, reason := a.locked(func() (StepOutcome, string) {
		// Re-checked under the lock, immediately before the selection
		// changes: waiting for the lock or a staging download must not
		// let an expired command act.
		if !a.now().Before(expires) {
			return OutcomeRetry, "step command expired before it could be applied"
		}
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		if outcome, reason := a.admit(command); outcome != "" {
			return outcome, reason
		}
		if command.Action == StepRollback {
			return a.restore(command)
		}
		return a.activate(command, window)
	})
	if !outcome.Accepted() {
		return outcome, reason
	}
	owed, err := a.owed()
	if err != nil {
		return OutcomeRetry, "restart obligation is unreadable"
	}
	if !owed || a.served == command.OperationID && outcome != OutcomeActivated {
		return outcome, reason
	}
	if err := a.restart(ctx); err != nil {
		slog.WarnContext(ctx, "rollout agent could not restart its unit", "component", "rollout", "unit", a.Unit, "error", err)
		return OutcomeRetry, "unit restart failed"
	}
	a.served = command.OperationID
	return outcome, reason
}

func (a *Agent) admit(command StepCommand) (StepOutcome, string) {
	if err := a.Layout.AdmitEpoch(command.Epoch); errors.Is(err, selfupdate.ErrStaleEpoch) {
		return OutcomeRefused, "step is from an older authority epoch"
	} else if err != nil {
		return OutcomeRetry, "authority epoch record is unreadable"
	}
	return "", ""
}

func (a *Agent) owed() (bool, error) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return false, err
	}
	defer unlock()
	return a.Layout.RestartPending(a.SystemdUnit)
}

func (a *Agent) locked(step func() (StepOutcome, string)) (StepOutcome, string) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return OutcomeRetry, "release root is locked"
	}
	defer unlock()
	return step()
}

func (a *Agent) ensureStaged(ctx context.Context, command StepCommand) (StepOutcome, string) {
	err := a.Layout.VerifyRelease(command.Digest)
	switch {
	case err == nil:
		return "", ""
	case !errors.Is(err, fs.ErrNotExist):
		return OutcomeRefused, "staged release does not verify"
	case a.Fetch == nil || len(command.Receipt) == 0:
		return OutcomeRefused, "release is not staged and cannot be restaged"
	}
	staged, err := a.Fetch.Fetch(ctx, a.Layout, command.Receipt, command.Delegation)
	if err != nil {
		slog.WarnContext(ctx, "rollout agent could not stage a release", "component", "rollout", "unit", a.Unit,
			"digest", command.Digest, "error", err)
		return OutcomeRetry, "release staging failed"
	}
	if staged != command.Digest {
		return OutcomeRefused, "the step's receipt names another release"
	}
	return "", ""
}

func (a *Agent) activate(command StepCommand, window time.Duration) (StepOutcome, string) {
	digest := command.Digest
	pending, exists, err := a.Layout.Pending()
	if err != nil {
		return OutcomeRetry, "activation state is unreadable"
	}
	if exists && (pending.Target != digest || pending.Unit != a.SystemdUnit || pending.Previous != command.Replaces) {
		// The watchdog resolves the other activation by its deadline.
		return OutcomeRetry, "another activation is pending"
	}
	if !exists {
		if current, err := a.Layout.Current(); err != nil {
			return OutcomeRetry, "current release is unreadable"
		} else if current == digest {
			return OutcomeCurrent, ""
		} else if current != command.Replaces {
			// A forward step only moves the unit off the rollout's
			// predecessor: a replayed step of an earlier rollout never
			// undoes the update that settled after it.
			return OutcomeRefused, "the unit does not run the step's predecessor release"
		}
		// Owed before the link moves, so an interruption after it never
		// leaves the old process running until the watchdog rejects a
		// release that never started.
		if err := a.Layout.MarkRestartPending(a.SystemdUnit); err != nil {
			return OutcomeRetry, "restart obligation could not be recorded"
		}
	}
	if _, err := selfupdate.Activate(a.Layout, digest, a.SystemdUnit, a.now(), window); err != nil {
		if !exists {
			// Nothing to restart unless the activation record was written;
			// an unreadable activation state keeps the obligation.
			if _, recorded, pendingErr := a.Layout.Pending(); pendingErr == nil && !recorded {
				_ = a.Layout.ClearRestartPending(a.SystemdUnit)
			}
		}
		if errors.Is(err, selfupdate.ErrKnownBad) {
			return OutcomeRefused, "release is known bad on this node"
		}
		slog.Warn("rollout agent could not activate a release", "component", "rollout", "unit", a.Unit,
			"digest", digest, "error", err)
		return OutcomeRetry, "activation failed"
	}
	if exists {
		return OutcomePending, ""
	}
	return OutcomeActivated, ""
}

func (a *Agent) restore(command StepCommand) (StepOutcome, string) {
	if pending, exists, err := a.Layout.Pending(); err != nil {
		return OutcomeRetry, "activation state is unreadable"
	} else if exists && (pending.Unit != a.SystemdUnit || pending.Target != command.Replaces || pending.Previous != command.Digest) {
		return OutcomeRetry, "another activation is pending"
	}
	changed, err := selfupdate.Restore(a.Layout, command.Digest, command.Replaces, a.SystemdUnit)
	switch {
	case errors.Is(err, selfupdate.ErrKnownBad):
		return OutcomeRefused, "release is known bad on this node"
	case errors.Is(err, selfupdate.ErrInvalid):
		return OutcomeRefused, "the unit runs neither release of the rollout"
	case err != nil:
		slog.Warn("rollout agent could not restore a release", "component", "rollout", "unit", a.Unit,
			"digest", command.Digest, "error", err)
		return OutcomeRetry, "restore failed"
	case !changed:
		return OutcomeCurrent, ""
	}
	return OutcomeActivated, ""
}

func (a *Agent) restart(ctx context.Context) error {
	if a.Restart == nil {
		return errors.New("no restarter")
	}
	return a.Restart(ctx, a.SystemdUnit)
}

func (command StepCommand) validate() error {
	if command.Schema != StepSchema || !unitRE.MatchString(command.Cell) || !entityid.Valid(command.RolloutID) ||
		command.Kind != rollout.KindController && command.Kind != rollout.KindHost || !unitRE.MatchString(command.Unit) ||
		!entityid.Valid(command.OperationID) || command.Action != StepPrepare && command.Action != StepRollback ||
		!digestRE.MatchString(command.Digest) || command.Epoch == 0 || command.ProofWindowSeconds <= 0 ||
		len(command.Receipt) > maxReleaseWire || len(command.Delegation) > maxReleaseWire ||
		len(command.Delegation) > 0 && len(command.Receipt) == 0 ||
		!digestRE.MatchString(command.Replaces) || command.Replaces == command.Digest {
		return fmt.Errorf("%w: step command", ErrInvalid)
	}
	return nil
}

func stepScope(command StepCommand) trust.Scope {
	return trust.Scope{Domain: StepDomain, DeploymentID: command.OperationID, Cell: command.Cell,
		Environment: stepEnvironment, Role: string(command.Action), Slot: command.Unit}
}

func SignStepCommand(command StepCommand, key ed25519.PrivateKey, now, deadline time.Time) ([]byte, error) {
	if err := command.validate(); err != nil {
		return nil, err
	}
	expires := now.Add(StepLifetime)
	if !deadline.IsZero() && deadline.Before(expires) {
		expires = deadline
	}
	if !expires.After(now) {
		return nil, fmt.Errorf("%w: step deadline has passed", ErrInvalid)
	}
	payload, err := trust.EncodePayload(command)
	if err != nil {
		return nil, err
	}
	envelope, err := trust.Sign(payload, stepScope(command), now, expires, key)
	if err != nil {
		return nil, err
	}
	return trust.EncodeEnvelope(envelope)
}

func VerifyStepCommand(wire []byte, cell, unit string, keys trust.Keyring, now time.Time) (StepCommand, time.Time, error) {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	scope := envelope.Scope
	if scope.Domain != StepDomain || scope.Cell != cell || scope.Slot != unit || scope.Environment != stepEnvironment ||
		scope.Role != string(StepPrepare) && scope.Role != string(StepRollback) {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	payload, err := trust.VerifyCurrent(envelope, scope, keys, now, trust.Policy{MaxLifetime: StepLifetime, ClockSkew: stepClockSkew})
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	var command StepCommand
	if err := protocol.DecodeStrict(payload, &command, trust.MaxPayloadBytes); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if err := command.validate(); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if stepScope(command) != scope {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	return command, envelope.ExpiresAt, nil
}

func (outcome StepOutcome) Accepted() bool {
	return outcome == OutcomeActivated || outcome == OutcomePending || outcome == OutcomeCurrent
}

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) ReleaseDir(digest string) string {
	return filepath.Join(layout.releasesPath(), digest)
}

func (layout Layout) BinaryPath(digest string) string {
	return filepath.Join(layout.ReleaseDir(digest), BinaryName)
}

func (layout Layout) CurrentExecutable() string {
	return filepath.Join(layout.currentPath(), BinaryName)
}

func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil
}

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil
}

func (layout Layout) Lock() (func(), error) {
	if err := layout.ensureDirs(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, lockFile)
	fd, err := syscall.Open(path, syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	if err := layout.checkOwned(path, false); err != nil {
		file.Close()
		return nil, err
	}
	for {
		err = syscall.Flock(fd, syscall.LOCK_EX)
		if !errors.Is(err, syscall.EINTR) {
			break
		}
	}
	if err != nil {
		file.Close()
		return nil, &os.PathError{Op: "flock", Path: path, Err: err}
	}
	return func() { file.Close() }, nil
}

func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

func writeSyncedFile(path string, data []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	_, err = file.Write(data)
	if err == nil {
		err = file.Chmod(mode)
	}
	if err == nil {
		err = file.Sync()
	}
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	return err
}

func (activation Activation) validate() error {
	if activation.Schema != ActivationSchema || !digestRE.MatchString(activation.Target) ||
		!digestRE.MatchString(activation.Previous) || activation.Target == activation.Previous ||
		!entityid.Valid(activation.ActivationID) || !unitRE.MatchString(activation.Unit) ||
		activation.ActivatedAt.IsZero() || !activation.Deadline.After(activation.ActivatedAt) ||
		activation.Deadline.Sub(activation.ActivatedAt) > MaxProofWindow {
		return fmt.Errorf("%w: activation record", ErrInvalid)
	}
	return nil
}

func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) markKnownBad(digest string) error {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	var state knownBadState
	switch {
	case errors.Is(err, os.ErrNotExist):
	case err != nil:
		return err
	default:
		if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
			return err
		}
	}
	if slices.Contains(state.Digests, digest) {
		return nil
	}
	state.Digests = append(state.Digests, digest)
	if len(state.Digests) > maxKnownBad {
		state.Digests = state.Digests[len(state.Digests)-maxKnownBad:]
	}
	encoded, err := protocol.EncodeJSON(state)
	if err != nil {
		return err
	}
	return writeFileAtomic(layout.knownBadPath(), encoded, 0o644)
}

func (layout Layout) AcceptedEpoch() (uint64, error) {
	if err := layout.checkOwned(layout.epochPath(), false); errors.Is(err, os.ErrNotExist) {
		return 0, nil
	} else if err != nil {
		return 0, err
	}
	data, err := readBounded(layout.epochPath(), 64)
	if err != nil {
		return 0, err
	}
	epoch, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil || epoch == 0 {
		return 0, fmt.Errorf("%w: accepted authority epoch", ErrInvalid)
	}
	return epoch, nil
}

func (layout Layout) AdmitEpoch(epoch uint64) error {
	if epoch == 0 {
		return fmt.Errorf("%w: authority epoch", ErrInvalid)
	}
	accepted, err := layout.AcceptedEpoch()
	if err != nil {
		return err
	}
	switch {
	case epoch < accepted:
		return ErrStaleEpoch
	case epoch == accepted:
		return nil
	}
	if err := layout.ensureDirs(); err != nil {
		return err
	}
	return writeFileAtomic(layout.epochPath(), fmt.Appendf(nil, "%d\n", epoch), 0o644)
}

func (layout Layout) restartMarkerPath(unit string) string {
	return filepath.Join(layout.Root, restartMarkerPrefix+unit)
}

func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func (layout Layout) restoreIntentPath(unit string) string {
	return filepath.Join(layout.Root, restoreIntentPrefix+unit+".json")
}

func Restore(layout Layout, digest, rejected, unit string) (bool, error) {
	if !digestRE.MatchString(digest) || !digestRE.MatchString(rejected) || digest == rejected || !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: restore target", ErrInvalid)
	}
	if err := layout.finishRestores(); err != nil {
		return false, err
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return false, err
	} else if knownBad[digest] {
		return false, ErrKnownBad
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return false, err
	}
	activation, pending, err := layout.Pending()
	if err != nil {
		return false, err
	}
	if pending {
		if activation.Unit != unit || activation.Target != rejected || activation.Previous != digest {
			return false, fmt.Errorf("%w: activation %s is pending for another release", ErrInvalid, activation.ActivationID)
		}
		if err := layout.rollback(activation); err != nil {
			return true, err
		}
		recordResolution(activation, OutcomeRolledBack)
		return true, nil
	}
	current, err := layout.Current()
	if err != nil {
		return false, err
	}
	switch current {
	case digest:
		// The unit never left digest, but the rollout rejected the other
		// release: this node must refuse it from now on too. Nothing
		// changed the selection, so no restart is owed.
		return false, layout.markKnownBad(rejected)
	case rejected:
	default:
		return false, fmt.Errorf("%w: the current release is neither the restore target nor the rejected release", ErrInvalid)
	}
	// There is no activation record to recover an interrupted restore
	// from, so a durable intent names the target first; finishRestore
	// completes the switch from it at any later point.
	intent, err := protocol.EncodeJSON(RestoreIntent{Schema: restoreIntentSchema, Unit: unit, Target: digest, Rejected: rejected})
	if err != nil {
		return false, err
	}
	if err := writeFileAtomic(layout.restoreIntentPath(unit), intent, 0o644); err != nil {
		return false, err
	}
	if err := layout.finishRestore(unit); err != nil {
		return true, err
	}
	decisionlog.Record(context.Background(), decisionlog.Decision{
		Actor:   decisionlog.Actor{Slice: "selfupdate"},
		Kind:    decisionlog.KindRollback,
		Subject: memberSubject(unit),
		Summary: "Restored release " + shortDigest(digest) + " on " + unit,
		Reason:  "A rollout rolled back the release this unit ran; that release is now known bad on this node.",
		Rule:    "selfupdate.restore",
		Status:  decisionlog.StatusRolledBack,
		Attrs:   map[string]string{"version": digest, "rejected": rejected},
	})
	return true, nil
}

func (layout Layout) finishRestores() error {
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := layout.finishRestore(intent.Unit); err != nil {
			return err
		}
	}
	return nil
}

func (layout Layout) PendingRestores() ([]RestoreIntent, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	if err := layout.checkOwned(layout.Root, true); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.Root)
	if err != nil {
		return nil, err
	}
	var intents []RestoreIntent
	for _, entry := range entries {
		unit, ok := strings.CutPrefix(entry.Name(), restoreIntentPrefix)
		if !ok {
			continue
		}
		unit, ok = strings.CutSuffix(unit, ".json")
		if !ok || !unitRE.MatchString(unit) {
			return nil, fmt.Errorf("%w: restore intent %q", ErrUnsafe, entry.Name())
		}
		if _, pending, err := layout.Pending(); err != nil {
			return nil, err
		} else if pending {
			return nil, fmt.Errorf("%w: restore intent of %s next to a pending activation", ErrUnsafe, unit)
		}
		intent, err := layout.readRestoreIntent(unit)
		if err != nil {
			return nil, err
		}
		intents = append(intents, intent)
	}
	return intents, nil
}

func (layout Layout) readRestoreIntent(unit string) (RestoreIntent, error) {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); err != nil {
		return RestoreIntent{}, err
	}
	data, err := readBounded(path, maxStateBytes)
	if err != nil {
		return RestoreIntent{}, err
	}
	var intent RestoreIntent
	if err := protocol.DecodeStrict(data, &intent, maxStateBytes); err != nil {
		return RestoreIntent{}, err
	}
	if intent.Schema != restoreIntentSchema || intent.Unit != unit || !digestRE.MatchString(intent.Target) ||
		!digestRE.MatchString(intent.Rejected) || intent.Target == intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: restore intent", ErrInvalid)
	}
	current, err := layout.Current()
	if err != nil {
		return RestoreIntent{}, err
	}
	if current != intent.Target && current != intent.Rejected {
		return RestoreIntent{}, fmt.Errorf("%w: current differs from recorded restore", ErrUnsafe)
	}
	bad, err := layout.KnownBad()
	if err != nil {
		return RestoreIntent{}, err
	}
	if bad[intent.Target] {
		return RestoreIntent{}, ErrKnownBad
	}
	if err := layout.VerifyRelease(intent.Target); err != nil {
		return RestoreIntent{}, fmt.Errorf("restore target cannot be restored: %w", err)
	}
	return intent, nil
}

func (layout Layout) finishRestore(unit string) error {
	path := layout.restoreIntentPath(unit)
	if err := layout.checkOwned(path, false); errors.Is(err, os.ErrNotExist) {
		return nil
	} else if err != nil {
		return err
	}
	intent, err := layout.readRestoreIntent(unit)
	if err != nil {
		return err
	}
	if err := layout.markKnownBad(intent.Rejected); err != nil {
		return err
	}
	if err := layout.markRestartPending(unit); err != nil {
		return err
	}
	if current, err := layout.Current(); err != nil {
		return err
	} else if current != intent.Target {
		if err := layout.flipCurrent(intent.Target); err != nil {
			return err
		}
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

func (layout Layout) MarkRestartPending(unit string) error {
	return layout.markRestartPending(unit)
}

func (layout Layout) rollback(activation Activation) error {
	if err := layout.markKnownBad(activation.Target); err != nil {
		return err
	}
	if err := layout.VerifyRelease(activation.Previous); err != nil {
		return fmt.Errorf("previous release cannot be restored: %w", err)
	}
	if err := layout.flipCurrent(activation.Previous); err != nil {
		return err
	}
	// The rejected process may still run: keep a restart obligation that
	// outlives this invocation before the activation record goes away.
	if err := layout.markRestartPending(activation.Unit); err != nil {
		return err
	}
	if err := os.Remove(layout.activationPath()); err != nil {
		return err
	}
	return syncDir(layout.Root)
}

func activationCorrelation(activation Activation) string {
	return "selfupdate:" + activation.ActivationID
}

func memberSubject(unit string) decisionlog.Subject {
	name, err := os.Hostname()
	if err != nil || name == "" {
		name = strings.TrimSuffix(unit, ".service")
	}
	return decisionlog.Subject{Kind: "member", ID: name, Name: unit}
}

func shortDigest(digest string) string {
	if len(digest) > 12 {
		return digest[:12]
	}
	return digest
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	return protocol.KeyID(publicKey)
}

func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

func verifySignature(envelope Envelope, expected Scope, keys Keyring, maximumLifetime time.Duration) error {
	if err := envelope.validateShape(); err != nil {
		return err
	}
	if err := expected.validate(); err != nil {
		return err
	}
	if envelope.Scope != expected {
		return ErrScopeMismatch
	}
	if !envelope.ExpiresAt.After(envelope.IssuedAt) || envelope.ExpiresAt.Sub(envelope.IssuedAt) > maximumLifetime {
		return fmt.Errorf("%w: invalid or excessive trust validity interval", ErrInvalid)
	}
	publicKey, exists := keys[envelope.KeyID]
	if !exists {
		return ErrUntrustedKey
	}
	keyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if keyID != envelope.KeyID {
		return ErrKeyMismatch
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := decodeCanonicalSignature(envelope.Signature)
	if err != nil || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func (envelope Envelope) validateShape() error {
	if envelope.SchemaVersion != SchemaVersion || !domainRE.MatchString(envelope.Scope.Domain) || envelope.KeyID == "" || envelope.Signature == "" ||
		!canonicalTime(envelope.IssuedAt) || !canonicalTime(envelope.ExpiresAt) {
		return fmt.Errorf("%w: envelope header", ErrInvalid)
	}
	if _, err := decodeCanonicalSignature(envelope.Signature); err != nil {
		return err
	}
	if err := envelope.Scope.validate(); err != nil {
		return err
	}
	_, err := compactPayload(envelope.Payload)
	return err
}

func (scope Scope) validate() error {
	if !domainRE.MatchString(scope.Domain) {
		return fmt.Errorf("%w: scope domain", ErrInvalid)
	}
	if scope.Domain == DelegationDomain && scope == delegationScope() {
		return nil
	}
	if !entityid.Valid(scope.DeploymentID) || !cellRE.MatchString(scope.Cell) ||
		!tokenRE.MatchString(scope.Environment) || !tokenRE.MatchString(scope.Role) || !slotRE.MatchString(scope.Slot) {
		return fmt.Errorf("%w: incomplete or invalid scope", ErrInvalid)
	}
	return nil
}

func delegationScope() Scope {
	return Scope{
		Domain: DelegationDomain, DeploymentID: DelegationDeploymentID, Cell: delegationCell,
		Environment: delegationEnvironment, Role: delegationRole, Slot: delegationSlot,
	}
}

func compactPayload(payload []byte) (jsontext.Value, error) {
	if len(payload) == 0 || len(payload) > MaxPayloadBytes || !utf8.Valid(payload) {
		return nil, fmt.Errorf("%w: payload is empty, invalid UTF-8, or too large", ErrInvalid)
	}
	value := jsontext.Value(payload).Clone()
	if err := value.Compact(jsontext.AllowDuplicateNames(false), jsontext.AllowInvalidUTF8(false)); err != nil {
		return nil, fmt.Errorf("%w: invalid payload JSON: %v", ErrInvalid, err)
	}
	if len(value) == 0 || value.Kind() != jsontext.Kind('{') {
		return nil, fmt.Errorf("%w: payload must be a JSON object", ErrInvalid)
	}
	return value, nil
}

func validatePayload(payload []byte) error {
	_, err := compactPayload(payload)
	return err
}

func signingMaterial(envelope Envelope) ([]byte, error) {
	payload, err := compactPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	material := make([]byte, 0, len(signatureDomain)+256+sha256.Size)
	material = append(material, signatureDomain...)
	material = binary.BigEndian.AppendUint16(material, uint16(envelope.SchemaVersion))
	for _, field := range []string{
		envelope.KeyID, envelope.Scope.Domain, envelope.Scope.DeploymentID, envelope.Scope.Cell,
		envelope.Scope.Environment, envelope.Scope.Role, envelope.Scope.Slot,
		envelope.IssuedAt.Format(time.RFC3339Nano), envelope.ExpiresAt.Format(time.RFC3339Nano),
	} {
		if len(field) > 1<<16-1 {
			return nil, fmt.Errorf("%w: signed field exceeds limit", ErrInvalid)
		}
		material = binary.BigEndian.AppendUint16(material, uint16(len(field)))
		material = append(material, field...)
	}
	payloadDigest := sha256.Sum256(payload)
	material = append(material, payloadDigest[:]...)
	return material, nil
}

func validTime(value time.Time) bool {
	return !value.IsZero() && value.Year() >= 1 && value.Year() <= 9999
}

func canonicalTime(value time.Time) bool {
	return validTime(value) && value.Location() == time.UTC &&
		value.Format(time.RFC3339Nano) == value.UTC().Format(time.RFC3339Nano)
}

func decodeCanonicalSignature(encoded string) ([]byte, error) {
	signature, err := base64.RawURLEncoding.Strict().DecodeString(encoded)
	if err != nil || len(signature) != ed25519.SignatureSize || base64.RawURLEncoding.EncodeToString(signature) != encoded {
		return nil, ErrBadSignature
	}
	return signature, nil
}

func ParseKeyring(publicKeys ...ed25519.PublicKey) (Keyring, error) {
	keyring := make(Keyring, len(publicKeys))
	for _, publicKey := range publicKeys {
		keyID, err := KeyID(publicKey)
		if err != nil {
			return nil, err
		}
		if _, exists := keyring[keyID]; exists {
			return nil, fmt.Errorf("%w: duplicate trusted root", ErrInvalid)
		}
		keyring[keyID] = append(ed25519.PublicKey(nil), publicKey...)
	}
	if len(keyring) == 0 {
		return nil, fmt.Errorf("%w: empty trusted root set", ErrInvalid)
	}
	return keyring, nil
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: expected an Ed25519 public key", ErrInvalidEnvelope)
	}
	digest := sha256.Sum256(publicKey)
	return "sha256:" + hex.EncodeToString(digest[:]), nil
}

func NewAt(at time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	return ulid.MustNew(ulid.Timestamp(at), entropy).String()
}

func Parse(value string) (ulid.ULID, error) {
	id, err := ulid.ParseStrict(value)
	if err != nil || id == (ulid.ULID{}) || id.String() != value {
		return ulid.ULID{}, errors.New("entity ID must be a canonical uppercase ULID")
	}
	return id, nil
}

func Valid(value string) bool {
	_, err := Parse(value)
	return err == nil
}

func Derive(domain string, values ...string) string {
	h := sha256.New()
	for _, value := range append([]string{domain}, values...) {
		var size [8]byte
		binary.BigEndian.PutUint64(size[:], uint64(len(value)))
		h.Write(size[:])
		h.Write([]byte(value))
	}
	return ulid.MustNew(0, bytes.NewReader(h.Sum(nil)[:10])).String()
}

func EncodeJSON(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode protocol JSON: %w", err)
	}
	return encoded, nil
}

func DecodeStrict(data []byte, destination any, maxBytes int) error {
	return decode(data, destination, maxBytes, true)
}

func decode(data []byte, destination any, maxBytes int, rejectUnknown bool) error {
	if maxBytes == 0 {
		maxBytes = DefaultMaxJSONBytes
	}
	if maxBytes < 0 {
		return fmt.Errorf("%w: negative byte limit", ErrInvalidJSON)
	}
	if len(data) > maxBytes {
		return ErrJSONTooLarge
	}
	if !utf8.Valid(data) {
		return fmt.Errorf("%w: invalid UTF-8", ErrInvalidJSON)
	}
	if err := json.Unmarshal(data, destination,
		json.RejectUnknownMembers(rejectUnknown),
		jsontext.AllowDuplicateNames(false),
	); err != nil {
		return fmt.Errorf("decode protocol JSON: %w", err)
	}
	return nil
}
